def orbit(r,c):
    return {(r,c),(r,n-1-c),(n-1-r,c),(n-1-r,n-1-c),(c,r),(c,n-1-r),(n-1-c,r),(n-1-c,n-1-r)}
unc=[];conf=[]
for r in range(n):
 for c in range(n):
  if grid[r][c]==2:
   vals=[grid[a][b] for a,b in orbit(r,c) if grid[a][b]!=2]
   if not vals: unc.append((r,c))
   elif len(set(vals))>1: conf.append((r,c,vals))
   else: out[r][c]=vals[0]
